function parseCSVTable(csvText) {
  if (typeof csvText !== 'string' || csvText.trim() === '') {
    return {
      header: [],
      rows: [],
      issues: [{
        code: 'EMPTY_CSV',
        message: 'CSV 內容為空'
      }]
    };
  }

  const parsedRows = [];
  let row = [],
      cell = '',
      quoted = false,
      lineNumber = 1,
      rowStartLine = 1;

  const pushRow = () => {
    const values = [...row, cell].map(value => value.replace(/\r$/, '').trim());
    parsedRows.push({
      values,
      lineNumber: rowStartLine
    });
    row = [];
    cell = '';
    rowStartLine = lineNumber + 1;
  };

  for (let i = 0; i < csvText.length; i += 1) {
    const ch = csvText[i];

    if (quoted) {
      if (ch === '"' && csvText[i + 1] === '"') {
        cell += '"';
        i += 1;
      } else if (ch === '"') quoted = false;else {
        cell += ch;
        if (ch === '\n') lineNumber += 1;
      }
    } else if (ch === '"') quoted = true;else if (ch === ',') {
      row.push(cell);
      cell = '';
    } else if (ch === '\n') {
      pushRow();
      lineNumber += 1;
    } else cell += ch;
  }

  if (cell !== '' || row.length > 0) pushRow();
  const contentRows = parsedRows.filter(item => {
    const first = (item.values[0] || '').trim();
    return item.values.some(value => value !== '') && !first.startsWith('#');
  });

  if (contentRows.length < 2) {
    return {
      header: contentRows[0]?.values || [],
      rows: [],
      issues: [{
        code: 'CSV_NO_DATA_ROWS',
        message: 'CSV 缺少資料列'
      }]
    };
  }

  const header = contentRows[0].values;
  const rows = contentRows.slice(1).map(item => ({ ...item,
    object: Object.fromEntries(header.map((name, index) => [name, item.values[index] ?? '']))
  }));
  return {
    header,
    rows,
    issues: []
  };
}

function validateTable(table, config) {
  const issues = [...table.issues];
  const invalidRows = [];
  const expected = config.columns;

  if (table.header.length !== expected.length || expected.some((name, index) => table.header[index] !== name)) {
    issues.push({
      code: 'SCHEMA_HEADER_MISMATCH',
      message: `${config.label} 表頭與核准 Schema 不一致`
    });
  }

  const seenKeys = new Set();
  const validRows = table.rows.filter(item => {
    const rowIssues = [];
    if (item.values.length !== expected.length) rowIssues.push(`欄數 ${item.values.length}，預期 ${expected.length}`);

    for (const field of config.required || []) {
      if (!item.object[field]) rowIssues.push(`${field} 缺失`);
    }

    for (const field of config.dateColumns || []) {
      const value = item.object[field];
      if (value && !/^\d{4}-\d{2}-\d{2}$/.test(value)) rowIssues.push(`${field} 日期格式錯誤`);
    }

    for (const field of config.numericColumns || []) {
      const value = item.object[field];
      const missingAllowed = config.optionalNumeric?.has(field);

      if (value === '' || value === 'N/A') {
        if (!missingAllowed) rowIssues.push(`${field} 缺失`);
      } else if (!Number.isFinite(Number(value))) rowIssues.push(`${field} 不是有效數值`);
    }

    for (const [field, allowed] of Object.entries(config.enums || {})) {
      const value = item.object[field];
      if (value && !allowed.includes(value)) rowIssues.push(`${field} 值 ${value} 未核准`);
    }

    if (config.keyColumn) {
      const key = item.object[config.keyColumn];
      if (seenKeys.has(key)) rowIssues.push(`${config.keyColumn} 重複`);
      seenKeys.add(key);
    }

    if (rowIssues.length > 0) {
      invalidRows.push({
        lineNumber: item.lineNumber,
        key: item.object[config.keyColumn] || '',
        issues: rowIssues
      });
      return false;
    }

    return true;
  });

  if (invalidRows.length > 0) {
    issues.push({
      code: 'INVALID_ROWS_EXCLUDED',
      message: `${config.label} 已排除 ${invalidRows.length} 筆格式異常資料`
    });
  }

  return {
    valid: !issues.some(issue => issue.code === 'SCHEMA_HEADER_MISMATCH') && validRows.length > 0,
    validRows: validRows.map(item => item.object),
    invalidRows,
    issues
  };
}

function validateMasterContinuity(rows) {
  const expected = [];

  for (let year = 2021; year <= 2026; year += 1) {
    const maxQuarter = year === 2026 ? 1 : 4;

    for (let quarter = 1; quarter <= maxQuarter; quarter += 1) expected.push(`${year}Q${quarter}`);
  }

  const actual = rows.map(row => row.Quarter);
  const datesValid = rows.every(row => row.EstimatedEffectiveDate >= row.QuarterEndDate);
  return {
    valid: actual.length === 21 && actual.join('|') === expected.join('|') && datesValid,
    message: datesValid ? '季度連續性與有效日期順序通過' : '有效日期早於季末日'
  };
}

