          const latestPrice = prices[prices.length - 1];
          const x = scales.x.getPixelForValue(labels.length - 1);
          const y = scales.y.getPixelForValue(latestPrice);
          ctx.save();
          ctx.font = '800 10px JetBrains Mono, monospace';
          ctx.textAlign = 'left';
          ctx.fillStyle = '#dbeafe';
          ctx.strokeStyle = 'rgba(8, 13, 25, 0.88)';
          ctx.lineWidth = 4;
          const text = `${currentPb.toFixed(2)}x`;
          const labelX = Math.min(x + 8, chartArea.right - 48);
          const labelY = Math.max(chartArea.top + 16, y - 8);
          ctx.fillStyle = 'rgba(15, 23, 42, 0.82)';
          ctx.fillRect(labelX - 4, labelY - 13, 44, 17);
          ctx.fillStyle = '#dbeafe';
